#include <string>
using namespace std;

vector<int> zFunction(const string& s) {
    int n = (int)s.size();
    vector<int> z(n, 0);
    z[0] = n;
    int l = 0, rr = 0;
    for (int i = 1; i < n; i++) {
        if (i < rr) z[i] = min(rr - i, z[i - l]);
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;
        if (i + z[i] > rr) {
            l = i;
            rr = i + z[i];
        }
    }
    return z;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int n = (int)s.size();
    vector<int> z = zFunction(s);
    long long count = 0;
    for (int L = 1; 2 * L <= n; L++) if (z[L] >= L) count++;
    cout << count << "\n";

    return 0;
}

